import torch
import triton
import triton.language as tl


@triton.jit
def mish_backward_kernel(
    grad_ptr,
    x_ptr,
    out_ptr,
    n_elements,
    BLOCK_SIZE: tl.constexpr,
):
    pid = tl.program_id(0)
    num_programs = tl.num_programs(0)
    num_blocks = tl.cdiv(n_elements, BLOCK_SIZE)
    blocks_per_program = tl.cdiv(num_blocks, num_programs)
    start_block = pid * blocks_per_program
    end_block = tl.minimum(start_block + blocks_per_program, num_blocks)

    for block_idx in range(start_block, end_block):
        offs = block_idx * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
        mask = offs < n_elements

        g = tl.load(grad_ptr + offs, mask=mask, other=0.0).to(tl.float32)
        x = tl.load(x_ptr + offs, mask=mask, other=0.0).to(tl.float32)

        # Single-exp algebraic form of the Mish derivative:
        #   u = e^x
        #   sigmoid(x)          = u / (1 + u)
        #   tanh(softplus(x))   = u(u+2) / (u(u+2) + 2)
        #   d/dx mish(x)        = t + x*s*(1 - t^2)
        # d -> 1 as x -> +inf, so clamp x at 20.0 (d(20) rounds to 1.0 in fp32)
        # and drop the separate log/exp(-x)/libdevice-tanh transcendentals.
        x_c = tl.minimum(x, 20.0)
        u = tl.exp(x_c)
        # Collapse sigmoid and tanh(softplus) into one algebraically exact
        # rational form to reduce two fp32 divisions to one:
        #   v = 1 + u
        #   sigmoid = (v-1)/v ;  tanh(softplus) = (v^2-1)/(v^2+1)
        #   d = ((v^4 - 1) + 4*x*(v-1)*v) / (v^2 + 1)^2
        v = 1.0 + u
        v2 = v * v
        denom2 = (v2 + 1.0) * (v2 + 1.0)
        num = v2 * v2 - 1.0 + 4.0 * x_c * u * v
        d = tl.fdiv(num, denom2, ieee_rounding=False)

        res = g * d
        tl.store(out_ptr + offs, res.to(out_ptr.dtype.element_ty), mask=mask)


def mish_backward(grad_output, input):
    if not grad_output.is_contiguous():
        grad_output = grad_output.contiguous()
    if not input.is_contiguous():
        input = input.contiguous()

    out_dtype = torch.result_type(grad_output, input)
    out = torch.empty_like(input, dtype=out_dtype)
    n_elements = input.numel()

    BLOCK_SIZE = 4096
    try:
        props = triton.runtime.driver.active.utils.get_device_properties(
            torch.npu.current_device()
        )
        nvc = props.get("num_vectorcore", 48)
    except Exception:
        nvc = 48

    num_blocks = triton.cdiv(n_elements, BLOCK_SIZE)
    grid = (min(num_blocks, nvc),)

    mish_backward_kernel[grid](
        grad_output, input, out, n_elements, BLOCK_SIZE=BLOCK_SIZE
    )
    return out
